package com.scapepath.plugin.game;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.Value;
import net.runelite.api.gameval.VarbitID;

/**
 * The auditable mapping of Combat Achievement state to the stable RuneLite {@code VarbitID}
 * constants that store it.
 *
 * <p>Unlike the Collection Log (whose per-item state is interface-gated and only partially
 * named), RuneLite's {@code gameval} exposes a stable, named per-task completion varbit for
 * <b>every</b> Combat Achievement task ({@code CA_TASK_&lt;ACTIVITY&gt;_&lt;TYPE&gt;_&lt;N&gt;_COMPLETED}).
 * These are account-stored varbits delivered with the login varp block, so they are reliable
 * whenever logged in and require no interface to be opened and no polling.</p>
 *
 * <p>The plugin sends only player <b>state</b>: which tasks are complete (by stable id), the
 * per-tier completed-task counts, tier status, points, and each tier's points threshold. The
 * website owns all static knowledge &mdash; which task belongs to which tier, its boss/activity,
 * its point value, and the full universe of tasks needed to compute "missing". The task id is
 * the RuneLite {@code VarbitID} constant name itself; it is stable across game updates and
 * independent of wiki wording, and the website must key on it, never on a display string.</p>
 *
 * <p>Reflection-free by design: every varbit is referenced by its named constant, so the
 * mapping is compile-checked and breaks loudly (not silently) if RuneLite renames a constant
 * on a version bump. Generated from RuneLite {@code runelite-api} 1.12.38.</p>
 */
public final class CombatAchievementDefinitions
{
	/** One Combat Achievement task and the varbit holding its completion. */
	@Value
	public static class TaskDef
	{
		/** Stable task id: the RuneLite {@code VarbitID} constant name. */
		String id;
		int varbitId;
	}

	/** One Combat Achievement tier and the varbits describing its aggregate state. */
	@Value
	public static class TierDef
	{
		/** Stable tier id, e.g. {@code "EASY"}. */
		String tier;
		/** Raw tier status varbit (game-defined; interpreted by the website). */
		int statusVarbitId;
		/** Count of completed tasks in this tier. */
		int completedCountVarbitId;
		/** Points threshold required to complete this tier. */
		int thresholdVarbitId;
	}

	/** A task varbit value of at least this is treated as completed. */
	public static final int TASK_COMPLETE_MIN = 1;

	/** VarPlayer/varbit holding the account's total Combat Achievement points. */
	public static final int POINTS_VARBIT = VarbitID.CA_POINTS;

	private static final List<TaskDef> TASKS = buildTasks();
	private static final List<TierDef> TIERS = buildTiers();
	private static final Set<Integer> VARBIT_IDS = collectVarbitIds();

	private CombatAchievementDefinitions()
	{
	}

	/** Every enumerated Combat Achievement task, in a fixed order. */
	public static List<TaskDef> tasks()
	{
		return TASKS;
	}

	/** The six Combat Achievement tiers, easiest first. */
	public static List<TierDef> tiers()
	{
		return TIERS;
	}

	/** Every varbit id this section reads &mdash; used to trigger targeted snapshot rebuilds. */
	public static Set<Integer> varbitIds()
	{
		return VARBIT_IDS;
	}

	private static void t(List<TaskDef> l, String id, int varbitId)
	{
		l.add(new TaskDef(id, varbitId));
	}

	private static List<TaskDef> buildTasks()
	{
		final List<TaskDef> l = new ArrayList<>(398);
		t(l, "CA_TASK_ABBERANT_SPECTRE_KILLCOUNT_1_COMPLETED", VarbitID.CA_TASK_ABBERANT_SPECTRE_KILLCOUNT_1_COMPLETED);
		t(l, "CA_TASK_ABYSSALSIRE_KILLCOUNT_1_COMPLETED", VarbitID.CA_TASK_ABYSSALSIRE_KILLCOUNT_1_COMPLETED);
		t(l, "CA_TASK_ABYSSALSIRE_KILLCOUNT_2_COMPLETED", VarbitID.CA_TASK_ABYSSALSIRE_KILLCOUNT_2_COMPLETED);
		t(l, "CA_TASK_ABYSSALSIRE_MECHANICAL_1_COMPLETED", VarbitID.CA_TASK_ABYSSALSIRE_MECHANICAL_1_COMPLETED);
		t(l, "CA_TASK_ABYSSALSIRE_MECHANICAL_2_COMPLETED", VarbitID.CA_TASK_ABYSSALSIRE_MECHANICAL_2_COMPLETED);
		t(l, "CA_TASK_ABYSSALSIRE_MECHANICAL_3_COMPLETED", VarbitID.CA_TASK_ABYSSALSIRE_MECHANICAL_3_COMPLETED);
		t(l, "CA_TASK_ABYSSALSIRE_MECHANICAL_4_COMPLETED", VarbitID.CA_TASK_ABYSSALSIRE_MECHANICAL_4_COMPLETED);
		t(l, "CA_TASK_ABYSSALSIRE_PERFECTION_1_COMPLETED", VarbitID.CA_TASK_ABYSSALSIRE_PERFECTION_1_COMPLETED);
		t(l, "CA_TASK_ABYSSALSIRE_PERFECTION_2_COMPLETED", VarbitID.CA_TASK_ABYSSALSIRE_PERFECTION_2_COMPLETED);
		t(l, "CA_TASK_ARMADYL_KILLCOUNT_1_COMPLETED", VarbitID.CA_TASK_ARMADYL_KILLCOUNT_1_COMPLETED);
		t(l, "CA_TASK_ARMADYL_KILLCOUNT_2_COMPLETED", VarbitID.CA_TASK_ARMADYL_KILLCOUNT_2_COMPLETED);
		t(l, "CA_TASK_ARMADYL_MECHANICAL_1_COMPLETED", VarbitID.CA_TASK_ARMADYL_MECHANICAL_1_COMPLETED);
		t(l, "CA_TASK_ARMADYL_MECHANICAL_2_COMPLETED", VarbitID.CA_TASK_ARMADYL_MECHANICAL_2_COMPLETED);
		t(l, "CA_TASK_ARMADYL_PERFECTION_1_COMPLETED", VarbitID.CA_TASK_ARMADYL_PERFECTION_1_COMPLETED);
		t(l, "CA_TASK_ARMADYL_RESTRICTION_1_COMPLETED", VarbitID.CA_TASK_ARMADYL_RESTRICTION_1_COMPLETED);
		t(l, "CA_TASK_ARMADYL_STAMINA_1_COMPLETED", VarbitID.CA_TASK_ARMADYL_STAMINA_1_COMPLETED);
		t(l, "CA_TASK_BANDOS_KILLCOUNT_1_COMPLETED", VarbitID.CA_TASK_BANDOS_KILLCOUNT_1_COMPLETED);
		t(l, "CA_TASK_BANDOS_KILLCOUNT_2_COMPLETED", VarbitID.CA_TASK_BANDOS_KILLCOUNT_2_COMPLETED);
		t(l, "CA_TASK_BANDOS_MECHANICAL_1_COMPLETED", VarbitID.CA_TASK_BANDOS_MECHANICAL_1_COMPLETED);
		t(l, "CA_TASK_BANDOS_MECHANICAL_2_COMPLETED", VarbitID.CA_TASK_BANDOS_MECHANICAL_2_COMPLETED);
		t(l, "CA_TASK_BANDOS_MECHANICAL_3_COMPLETED", VarbitID.CA_TASK_BANDOS_MECHANICAL_3_COMPLETED);
