	private static List<TierDef> buildTiers()
	{
		final List<TierDef> l = new ArrayList<>(6);
		l.add(new TierDef("EASY", VarbitID.CA_TIER_STATUS_EASY,
			VarbitID.CA_TOTAL_TASKS_COMPLETED_EASY, VarbitID.CA_THRESHOLD_EASY));
		l.add(new TierDef("MEDIUM", VarbitID.CA_TIER_STATUS_MEDIUM,
			VarbitID.CA_TOTAL_TASKS_COMPLETED_MEDIUM, VarbitID.CA_THRESHOLD_MEDIUM));
		l.add(new TierDef("HARD", VarbitID.CA_TIER_STATUS_HARD,
			VarbitID.CA_TOTAL_TASKS_COMPLETED_HARD, VarbitID.CA_THRESHOLD_HARD));
		l.add(new TierDef("ELITE", VarbitID.CA_TIER_STATUS_ELITE,
			VarbitID.CA_TOTAL_TASKS_COMPLETED_ELITE, VarbitID.CA_THRESHOLD_ELITE));
		l.add(new TierDef("MASTER", VarbitID.CA_TIER_STATUS_MASTER,
			VarbitID.CA_TOTAL_TASKS_COMPLETED_MASTER, VarbitID.CA_THRESHOLD_MASTER));
		l.add(new TierDef("GRANDMASTER", VarbitID.CA_TIER_STATUS_GRANDMASTER,
			VarbitID.CA_TOTAL_TASKS_COMPLETED_GRANDMASTER, VarbitID.CA_THRESHOLD_GRANDMASTER));
		return Collections.unmodifiableList(l);
	}

	private static Set<Integer> collectVarbitIds()
	{
		final Set<Integer> ids = new HashSet<>();
		ids.add(POINTS_VARBIT);
		for (TaskDef task : TASKS)
		{
			ids.add(task.getVarbitId());
		}
		for (TierDef tier : TIERS)
		{
			ids.add(tier.getStatusVarbitId());
			ids.add(tier.getCompletedCountVarbitId());
			ids.add(tier.getThresholdVarbitId());
		}
		return Collections.unmodifiableSet(ids);
	}
}

