			.varp(VarPlayerID.COLLECTION_COUNT_MAX, 1500)
			.varp(VarPlayerID.COLLECTION_COUNT, 573)
			.varp(VarPlayerID.COLLECTION_COUNT_BOSSES, 100)
			.varp(VarPlayerID.COLLECTION_COUNT_BOSSES_MAX, 400);

